export const GLOSSARY_SHARD = Object.freeze({"blockchain":{"slug":"blockchain","cat":"basics","en":"Blockchain","contentLocale":"vi","term":"Blockchain (chuỗi khối)","aka":["chuỗi khối","công nghệ blockchain"],"short":"Blockchain (chuỗi khối) là một sổ cái số được chia sẻ, trong đó các giao dịch được gom thành từng khối và nối với nhau theo thứ tự, nên muốn sửa dữ liệu cũ thì phải làm lại toàn bộ các khối phía sau.","body":[["Hãy hình dung một cuốn sổ kế toán không do ngân hàng nào giữ, mà được sao chép trên hàng nghìn máy tính (",["node","node"],") khắp thế giới. Mỗi khối chứa một nhóm giao dịch và mã băm (hash) của khối trước đó. Nếu ai đó sửa một khối cũ, mã băm sẽ thay đổi, chuỗi không còn khớp và các node khác sẽ từ chối."],["Để quyết định ai được thêm khối tiếp theo, mỗi mạng dùng một cơ chế đồng thuận. ",["Bitcoin","bitcoin"]," dùng ",["bằng chứng công việc","proof-of-work"]," (",["đào coin","mining"],"), còn ",["Ethereum","ethereum"]," dùng ",["bằng chứng cổ phần","proof-of-stake"]," (validator khóa ETH để xác thực). Kết quả là một lịch sử công khai mà bạn có thể tra cứu bằng trình khám phá khối (block explorer)."],"Với người dùng, điều quan trọng nhất là giao dịch đã xác nhận gần như không thể đảo ngược. Không có tổng đài nào hoàn tiền nếu bạn gửi nhầm địa chỉ hoặc nhầm mạng, nên hãy kiểm tra kỹ trước mỗi lần rút."],"example":"Giả sử bạn gửi 0,02 BTC cho một người bạn. Giao dịch sẽ nằm chờ trong hàng đợi cho đến khi thợ đào đưa nó vào một khối. Bitcoin tạo khối trung bình khoảng 10 phút một lần, nên sau 6 xác nhận (khoảng 60 phút) phần lớn sàn coi khoản nạp là chắc chắn. Nếu ai đó muốn xóa giao dịch của bạn ở khối số 2, họ phải làm lại khối đó cùng 4 khối phía sau nhanh hơn toàn bộ phần còn lại của mạng, điều này cực kỳ tốn kém trên một mạng lớn.","mistakes":["Nghĩ rằng blockchain lưu coin bên trong ứng dụng sàn, trong khi nó chỉ ghi số dư gắn với các địa chỉ ví.","Tin rằng có thể nhờ hỗ trợ hủy một giao dịch đã được xác nhận trên chuỗi.","Cho rằng mọi blockchain đều giống nhau và gửi tiền qua mạng mà địa chỉ nhận không hỗ trợ."],"faq":[{"q":"Blockchain dùng để làm gì?","a":"Blockchain dùng để ghi lại giao dịch hoặc dữ liệu mà không một bên nào có thể tự ý sửa. Ứng dụng nổi tiếng nhất là tiền mã hóa, ngoài ra còn có hợp đồng thông minh, stablecoin và các ứng dụng DeFi."},{"q":"Blockchain và Bitcoin có phải là một?","a":"Không. Bitcoin là một đồng tiền mã hóa chạy trên blockchain riêng của nó, còn blockchain là công nghệ nền tảng mà nhiều mạng khác như Ethereum hay Solana cũng sử dụng."},{"q":"Dữ liệu trên blockchain có bị hack được không?","a":"Sửa lịch sử của một blockchain lớn là cực kỳ khó và tốn kém. Phần lớn vụ mất tiền xảy ra ở lớp bên trên, như ví bị lộ khóa riêng tư, hợp đồng thông minh có lỗi hoặc sàn bị tấn công."}],"title":"Blockchain là gì? Chuỗi khối hoạt động thế nào","description":"Blockchain là gì, các khối được nối với nhau ra sao và vì sao giao dịch đã xác nhận gần như không thể đảo ngược.","related":[["cryptocurrency","Tiền mã hóa (Cryptocurrency)","Tiền mã hóa (cryptocurrency) là tài sản số được ghi nhận trên blockchain, chuyển trực tiếp giữa các ví mà không cần ngân hàng trung gian, và quyền sở hữu được bảo vệ bằng khóa riêng tư."],["proof-of-work","Bằng chứng công việc (Proof of Work - PoW)","Bằng chứng công việc (Proof of Work, PoW) là cơ chế đồng thuận trong đó thợ đào dùng sức mạnh tính toán để giải bài toán mật mã, ai tìm ra lời giải trước sẽ được thêm khối mới và nhận thưởng."],["proof-of-stake","Bằng chứng cổ phần (Proof of Stake - PoS)","Bằng chứng cổ phần (Proof of Stake, PoS) là cơ chế đồng thuận trong đó validator khóa coin của mạng làm tài sản đảm bảo để được quyền đề xuất và xác thực khối mới, thay cho việc đào bằng máy."],["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."],["block-explorer","Block explorer (trình khám phá khối)","Block explorer là trang web cho phép bạn tra cứu mọi giao dịch, địa chỉ ví và khối trên một blockchain, giống như công cụ tra cứu sao kê công khai của mạng đó."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"trading-volume":{"slug":"trading-volume","cat":"trading","en":"Trading volume","contentLocale":"vi","term":"Khối lượng giao dịch (Volume)","aka":["volume","vol","khối lượng giao dịch 24h"],"short":"Khối lượng giao dịch là tổng giá trị hoặc số lượng một tài sản đã được mua bán trong một khoảng thời gian, thường tính trong 24 giờ.","body":[["Volume cho biết thị trường đang sôi động đến đâu. Trên ",["biểu đồ nến","candlestick-chart"],", các cột volume nằm bên dưới cho thấy mỗi cây nến có bao nhiêu giao dịch. Một cú tăng hoặc giảm giá đi kèm volume lớn thường được xem là có nhiều người tham gia hơn một cú ",["biến động","volatility"]," với volume nhỏ."],["Volume có thể đo bằng số coin hoặc quy đổi ra ",["USDT","usdt"],", USD. Các trang tổng hợp dữ liệu cộng volume của nhiều sàn lại. Volume của ",["hợp đồng tương lai","futures-contract"]," thường lớn hơn spot nhiều lần vì có ",["đòn bẩy","leverage"],", nên bạn cần biết mình đang xem loại volume nào."],["Volume không phải lúc nào cũng phản ánh nhu cầu thật. Một số sàn hoặc dự án từng bị nghi tạo volume giả bằng ",["wash trading","wash-trading"],", vì vậy bạn nên đối chiếu nhiều nguồn."]],"example":"Giả sử một coin có giá 2 USDT và trong 24 giờ có 15 triệu coin được khớp lệnh. Volume 24h tính theo USDT xấp xỉ 15.000.000 × 2 = 30 triệu USDT. Hôm sau giá tăng 12% nhưng volume chỉ còn 8 triệu USDT. Mức tăng này có ít người tham gia hơn, nên bạn nên thận trọng khi đọc nó như một xu hướng mạnh.","mistakes":["Nhầm volume với vốn hóa thị trường, hai chỉ số đo hai thứ khác nhau.","Tin tuyệt đối vào volume của một sàn nhỏ mà không so sánh với các sàn lớn.","So sánh volume spot với volume hợp đồng tương lai như thể chúng giống nhau."],"faq":[{"q":"Volume cao có nghĩa là giá sẽ tăng không?","a":"Không. Volume chỉ cho biết mức độ giao dịch, không cho biết hướng giá. Volume cao có thể xuất hiện cả khi giá giảm mạnh."},{"q":"Volume 24h là gì?","a":"Đó là tổng giá trị giao dịch của một coin hoặc một sàn trong 24 giờ gần nhất, tính liên tục chứ không theo ngày lịch."}],"title":"Volume là gì? Khối lượng giao dịch trong crypto","description":"Khối lượng giao dịch (volume) là gì, cách đọc cột volume trên biểu đồ và vì sao không nên tin volume một cách tuyệt đối.","related":[["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["market-capitalization","Vốn hóa thị trường (Market cap)","Vốn hóa thị trường (market cap) của một đồng tiền mã hóa là giá hiện tại nhân với nguồn cung lưu hành, cho biết tổng giá trị thị trường đang định cho lượng coin đang lưu thông."],["open-interest","Hợp đồng mở (Open interest)","Hợp đồng mở (open interest, OI) là tổng số lượng hoặc giá trị các hợp đồng phái sinh đang còn mở và chưa được đóng hay tất toán tại một thời điểm."],["wash-trading","Wash trading (giao dịch giả)","Wash trading là việc một người hoặc một nhóm tự mua và tự bán cùng một tài sản với chính mình để tạo ra khối lượng giao dịch giả, khiến thị trường trông sôi động hơn thực tế."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"position-sizing":{"slug":"position-sizing","cat":"trading","en":"Position sizing","contentLocale":"vi","term":"Quản lý khối lượng vị thế (Position sizing)","aka":["position sizing","khối lượng vị thế","quy mô vị thế"],"short":"Position sizing là cách xác định bạn nên mở một lệnh lớn bao nhiêu, dựa trên số tiền bạn chấp nhận mất nếu lệnh chạm cắt lỗ.","body":[["Nguyên tắc phổ biến là chỉ chấp nhận mất một phần nhỏ tổng vốn cho mỗi lệnh, ví dụ 1-2%. Sau đó bạn tính khối lượng vị thế từ khoảng cách giữa giá vào lệnh và giá ",["cắt lỗ","stop-loss"],". Cắt lỗ càng xa thì vị thế càng nhỏ, và ngược lại."],"Công thức đơn giản: khối lượng = số tiền chấp nhận rủi ro / khoảng cách cắt lỗ. Cách này giúp một chuỗi lệnh thua không xóa sổ tài khoản, và giúp bạn so sánh các cơ hội trên cùng một thước đo.",["Khi dùng ",["đòn bẩy","leverage"],", position sizing càng quan trọng. Đòn bẩy chỉ thay đổi số ký quỹ cần bỏ ra, không thay đổi số tiền bạn mất khi giá chạm cắt lỗ. Bạn cũng phải đảm bảo ",["giá thanh lý","liquidation-price"]," nằm xa hơn giá cắt lỗ."]],"example":["Giả sử tài khoản của bạn có 5.000 ",["USDT","usdt"]," và bạn chấp nhận rủi ro 1% mỗi lệnh, tức 50 USDT. Bạn muốn mua ",["ETH","ethereum"]," ở 2.500 USDT và đặt cắt lỗ ở 2.400 USDT, khoảng cách 100 USDT. Khối lượng vị thế là 50 / 100 = 0,5 ETH, trị giá 1.250 USDT. Nếu dùng đòn bẩy 5x, bạn chỉ cần 250 USDT ký quỹ, nhưng số tiền mất khi chạm cắt lỗ vẫn là 50 USDT."],"mistakes":["Chọn khối lượng theo cảm giác hoặc theo đòn bẩy tối đa thay vì theo khoảng cách cắt lỗ.","Quên cộng phí giao dịch và trượt giá vào số tiền rủi ro.","Tăng khối lượng sau mỗi lệnh thua để gỡ nhanh."],"faq":[{"q":"Nên rủi ro bao nhiêu phần trăm mỗi lệnh?","a":"Nhiều người giao dịch dùng mức 0,5-2% tổng vốn. Con số phù hợp tùy chiến lược và khả năng chịu lỗ liên tiếp của bạn."},{"q":"Đòn bẩy có làm tăng rủi ro nếu đã tính position sizing?","a":"Nếu khối lượng và cắt lỗ đã cố định, đòn bẩy không đổi số tiền lỗ khi chạm cắt lỗ. Nhưng đòn bẩy cao kéo giá thanh lý lại gần, có thể bị thanh lý trước khi chạm cắt lỗ."}],"title":"Position sizing là gì? Cách tính khối lượng lệnh","description":"Position sizing là gì, công thức tính khối lượng vị thế theo cắt lỗ và rủi ro 1-2% để bảo vệ tài khoản giao dịch.","related":[["risk-reward-ratio","Tỷ lệ rủi ro/lợi nhuận (Risk-reward ratio)","Tỷ lệ rủi ro/lợi nhuận (R:R) so sánh số tiền bạn có thể mất nếu chạm cắt lỗ với số tiền bạn có thể lãi nếu chạm chốt lời trong cùng một lệnh."],["stop-loss","Lệnh cắt lỗ (Stop-loss)","Lệnh cắt lỗ (stop-loss) là lệnh tự động đóng vị thế khi giá chạm một mức bạn đặt trước, nhằm giới hạn khoản lỗ trong trường hợp thị trường đi ngược kỳ vọng."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["liquidation","Thanh lý (Liquidation)","Thanh lý (hay cháy tài khoản) là khi sàn tự động đóng vị thế có đòn bẩy của bạn vì ký quỹ không còn đủ đáp ứng mức ký quỹ duy trì."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Xác định mức có thể mất trước khi quyết định mua bao nhiêu"},"coin":null,"tool":null,"cta":false},"funding-rate":{"slug":"funding-rate","cat":"derivatives","en":"Funding rate","contentLocale":"vi","term":"Funding rate (Tỷ lệ funding)","aka":["funding rate","phí funding","tỷ lệ funding","tỷ lệ tài trợ"],"short":"Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot.","body":[["Khi funding dương, giá perp thường cao hơn ",["giá chỉ số","index-price"],", phe long trả cho phe short. Khi funding âm, phe short trả cho phe long. Sàn không giữ khoản này; tiền chuyển trực tiếp giữa người giao dịch. Bạn chỉ trả hoặc nhận nếu đang giữ vị thế đúng thời điểm thanh toán."],["Khoản funding được tính trên giá trị vị thế, không phải trên ký quỹ. Vì vậy với ",["đòn bẩy","leverage"]," cao, funding có thể chiếm phần đáng kể trong ký quỹ của bạn. Chu kỳ phổ biến là 8 giờ, nhưng nhiều sàn và cặp dùng 1, 2 hoặc 4 giờ, và có mức trần riêng."],"Funding cũng là chỉ báo tâm lý: funding dương cao kéo dài cho thấy nhiều người long dùng đòn bẩy. Tuy vậy, nó không dự báo hướng giá một cách chắc chắn."],"example":["Giả sử bạn long ",["BTC","bitcoin"]," perp với giá trị vị thế 10.000 ",["USDT","usdt"],", dùng 1.000 USDT ký quỹ (10x). Funding là +0,03% mỗi 8 giờ. Mỗi lần thanh toán bạn trả 10.000 × 0,03% = 3 USDT, mỗi ngày 9 USDT. Sau 30 ngày bạn trả khoảng 270 USDT, tức 27% số ký quỹ, dù giá BTC có thể không đổi."],"mistakes":["Tính funding trên ký quỹ thay vì trên giá trị vị thế.","Nghĩ rằng funding âm chắc chắn là tín hiệu giá sắp tăng.","Không để ý chu kỳ funding của cặp mình giao dịch có thể ngắn hơn 8 giờ."],"faq":[{"q":"Funding rate âm có ý nghĩa gì?","a":"Funding âm nghĩa là phe short trả cho phe long, thường khi giá perp thấp hơn giá chỉ số. Nó phản ánh tâm lý nghiêng về short, không phải lời dự báo giá."},{"q":"Đóng vị thế trước giờ funding có phải trả không?","a":"Không. Bạn chỉ trả hoặc nhận funding nếu vị thế còn mở đúng thời điểm thanh toán."},{"q":"Funding rate bao lâu thanh toán một lần?","a":"Phổ biến là mỗi 8 giờ, nhưng một số sàn và cặp dùng 1, 2 hoặc 4 giờ. Hãy xem trang thông số hợp đồng."}],"title":"Funding rate là gì? Phí funding trong hợp đồng vĩnh cửu","description":"Funding rate là gì, ai trả cho ai, cách tính phí funding trên giá trị vị thế và vì sao nó quan trọng khi dùng đòn bẩy.","related":[["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["funding-rate-arbitrage","Arbitrage funding rate (Kinh doanh chênh lệch funding)","Arbitrage funding rate là chiến lược giữ vị thế trung lập về giá, thường là mua spot và short perpetual cùng lượng, để thu khoản funding được trả định kỳ."],["mark-price","Giá đánh dấu (Mark price)","Giá đánh dấu (mark price) là giá tham chiếu mà sàn dùng để tính lãi lỗ chưa thực hiện và quyết định thanh lý, được xây dựng từ giá chỉ số của nhiều sàn spot."],["index-price","Giá chỉ số (Index price)","Giá chỉ số (index price) là giá trung bình có trọng số của một tài sản trên nhiều sàn spot lớn, được dùng làm tham chiếu cho giá đánh dấu và funding rate."],["open-interest","Hợp đồng mở (Open interest)","Hợp đồng mở (open interest, OI) là tổng số lượng hoặc giá trị các hợp đồng phái sinh đang còn mở và chưa được đóng hay tất toán tại một thời điểm."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"Giá đi ngang, số dư giảm? Vượt qua ải cuối với bài toán chi phí"},"coin":null,"tool":"/funding-rates","cta":true},"defi":{"slug":"defi","cat":"defi","en":"DeFi (decentralized finance)","contentLocale":"vi","term":"DeFi (Tài chính phi tập trung)","aka":["DeFi","tài chính phi tập trung","decentralized finance"],"short":"DeFi (tài chính phi tập trung) là các dịch vụ tài chính như giao dịch, cho vay, gửi tiết kiệm chạy bằng hợp đồng thông minh trên blockchain, không cần ngân hàng hay sàn tập trung làm trung gian.","body":[["Thay vì mở tài khoản và để công ty giữ tiền, bạn kết nối ",["ví phi lưu ký","non-custodial-wallet"]," với ứng dụng và tương tác trực tiếp với hợp đồng. Các mảng chính gồm ",["DEX","dex"]," như Uniswap, cho vay như Aave, ",["stablecoin thế chấp crypto","crypto-backed-stablecoin"],", ",["staking thanh khoản","liquid-staking"]," và tổng hợp lợi suất."],["Ưu điểm là mở cho bất kỳ ai có ví, hoạt động 24/7, minh bạch vì mọi giao dịch nằm trên chuỗi, và các ứng dụng có thể ghép nối với nhau. Đổi lại, bạn chịu rủi ro lỗi hợp đồng, ",["oracle","oracle"]," bị thao túng, ",["thanh lý","liquidation"]," khi vay, phí gas, và không có bộ phận hỗ trợ hoàn tiền khi bạn ký nhầm."],"Quy định với DeFi còn đang phát triển và khác nhau theo quốc gia. Nhiều giao diện vẫn do một công ty vận hành dù hợp đồng phía sau là phi tập trung."],"example":"Giả sử bạn có 2 ETH. Trên một giao thức cho vay, bạn gửi 2 ETH làm tài sản thế chấp khi ETH ở mức giả định 3.000 USD, tức 6.000 USD. Bạn vay 2.000 USDC để dùng việc khác mà không bán ETH. Nếu ETH giảm đủ sâu để khoản vay chạm ngưỡng thanh lý, hợp đồng sẽ tự bán một phần ETH của bạn, không có ai gọi điện báo trước.","mistakes":["Gửi tiền vào giao thức mới chỉ vì APY cao mà không xem lịch sử kiểm toán và thời gian hoạt động.","Nghĩ rằng DeFi không có rủi ro đối tác chỉ vì không có công ty trung gian.","Quên tính phí gas, có thể ăn hết lợi nhuận với số vốn nhỏ trên Ethereum."],"faq":[{"q":"DeFi khác CeFi thế nào?","a":"CeFi như sàn tập trung giữ tiền hộ bạn và có bộ phận hỗ trợ. DeFi để bạn tự giữ tài sản và giao dịch qua hợp đồng thông minh, đổi lại bạn tự chịu trách nhiệm mọi thao tác."},{"q":"Người mới có nên dùng DeFi không?","a":"Có thể bắt đầu với số tiền nhỏ trên các giao thức lâu năm, sau khi đã hiểu ví, phí gas và cấp quyền token."}],"title":"DeFi là gì? Tài chính phi tập trung cho người mới","description":"DeFi là gì, hoạt động ra sao, các mảng chính như DEX, cho vay, staking, cùng những rủi ro người mới cần hiểu rõ.","related":[["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian."],["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."],["total-value-locked","Tổng giá trị khóa (TVL)","TVL (tổng giá trị khóa) là tổng giá trị tài sản crypto đang được gửi trong một giao thức DeFi hoặc một blockchain, thường tính bằng USD, dùng để đo quy mô và mức độ sử dụng."],["defi-lending","Cho vay DeFi (DeFi lending)","Cho vay DeFi là việc gửi crypto vào giao thức như Aave để nhận lãi, hoặc thế chấp crypto để vay tài sản khác, toàn bộ do hợp đồng thông minh quản lý thay cho ngân hàng."],["liquidity-pool","Pool thanh khoản (Liquidity pool)","Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cross-chain-bridge":{"slug":"cross-chain-bridge","cat":"defi","en":"Cross-chain bridge","contentLocale":"vi","term":"Cầu nối chuỗi chéo (Cross-chain bridge)","aka":["bridge","cầu nối","cross-chain bridge","cầu cross-chain"],"short":"Cầu nối chuỗi chéo là giao thức giúp chuyển tài sản hoặc dữ liệu giữa hai blockchain khác nhau, thường bằng cách khóa tài sản ở chuỗi gốc và phát hành bản đại diện ở chuỗi đích.","body":[["Các ",["blockchain","blockchain"]," không tự nói chuyện với nhau. Cầu nối kiểu khóa và phát hành giữ token của bạn trong hợp đồng ở chuỗi A rồi phát hành ",["token gói","wrapped-token"]," tương ứng ở chuỗi B. Một số cầu khác dùng ",["pool thanh khoản","liquidity-pool"]," ở cả hai đầu, hoặc ",["đốt token","token-burn"]," ở chuỗi này và phát hành gốc ở chuỗi kia, như cách một số ",["stablecoin","stablecoin"]," làm."],"Cầu nối là một trong những mục tiêu bị hack nhiều nhất trong crypto, vì hợp đồng giữ lượng tài sản rất lớn và thường dựa vào một nhóm người xác minh. Nếu cầu bị hack, token gói ở chuỗi đích có thể mất giá trị.","Trước khi bridge, hãy kiểm tra xem sàn có hỗ trợ rút thẳng sang chuỗi đích không, vì đó thường là cách đơn giản hơn. Nếu dùng cầu, hãy dùng giao diện chính thức và gửi thử khoản nhỏ."],"example":["Giả sử bạn có 1.000 ",["USDC","usdc"]," trên Ethereum và muốn dùng trên Arbitrum. Qua cầu nối chính thức, bạn trả phí gas Ethereum khoảng vài USD và chờ vài phút, nhận khoảng 1.000 USDC trên Arbitrum. Một lựa chọn khác: gửi 1.000 USDC lên sàn qua Ethereum, rồi rút về Arbitrum, chịu phí rút ví dụ 1 USDC. So sánh phí và thời gian trước khi chọn."],"mistakes":["Tìm cầu nối qua quảng cáo và kết nối ví với trang giả mạo.","Bridge toàn bộ số tiền lần đầu mà không gửi thử khoản nhỏ.","Không phân biệt token gốc với token gói từ cầu nối khi mang lên sàn."],"faq":[{"q":"Bridge mất bao lâu?","a":"Từ vài giây đến vài ngày, tùy loại cầu và chuỗi. Rút từ một số layer 2 lạc quan về Ethereum qua cầu gốc có thể mất khoảng 7 ngày."},{"q":"Gửi tiền qua cầu bị kẹt thì sao?","a":"Tra mã giao dịch ở cả hai chuỗi và trang trạng thái của cầu. Nhiều cầu có chức năng nhận thủ công ở chuỗi đích khi bước tự động chưa hoàn tất."}],"title":"Bridge là gì? Cầu nối chuỗi chéo trong crypto","description":"Cầu nối chuỗi chéo (bridge) là gì, cách chuyển tài sản giữa các blockchain, rủi ro bị hack và cách bridge an toàn hơn.","related":[["wrapped-token","Token gói (Wrapped token)","Token gói là token đại diện cho một tài sản khác theo tỷ lệ 1:1, ví dụ WBTC đại diện cho BTC trên Ethereum, giúp tài sản đó dùng được trên blockchain hoặc trong ứng dụng vốn không hỗ trợ nó."],["layer-2","Layer 2 (L2, giải pháp lớp 2)","Layer 2 (L2) là mạng xây trên một blockchain lớp 1, xử lý giao dịch bên ngoài chuỗi chính rồi gửi kết quả gom lại về L1, giúp giao dịch nhanh hơn và phí rẻ hơn."],["blockchain-network","Mạng nạp rút (Chọn mạng blockchain)","Mạng nạp rút là blockchain cụ thể mà một đồng coin được chuyển qua, ví dụ USDT có thể đi trên Tron (TRC20), Ethereum (ERC20) hay BNB Chain (BEP20); bên gửi và bên nhận phải dùng cùng mạng."],["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này"},"coin":null,"tool":null,"cta":false},"stablecoin":{"slug":"stablecoin","cat":"stablecoins","en":"Stablecoin","contentLocale":"vi","term":"Stablecoin (Đồng tiền ổn định)","aka":["stablecoin","đồng ổn định","coin ổn định"],"short":"Stablecoin là đồng crypto được thiết kế để giữ giá ổn định so với một tài sản tham chiếu, phổ biến nhất là 1 USD, như USDT và USDC.","body":[["Có ba nhóm chính. Stablecoin đảm bảo bằng tài sản pháp định như ",["USDT","usdt"],", ",["USDC","usdc"],": đơn vị phát hành giữ tiền mặt và trái phiếu ngắn hạn. ",["Stablecoin thế chấp crypto","crypto-backed-stablecoin"]," như DAI, USDS: được đảm bảo bằng crypto với tỷ lệ thế chấp vượt mức. Và loại tổng hợp hoặc thuật toán, dùng chiến lược phái sinh hay cơ chế cung cầu."],["Trên sàn, stablecoin là đơn vị định giá chính: hầu hết ",["cặp giao dịch","trading-pair"]," là ",["BTC","bitcoin"],"/USDT hay ",["ETH","ethereum"],"/USDC, ký quỹ futures thường bằng USDT hoặc USDC. Người dùng P2P cũng hay mua USDT bằng tiền nội tệ để vào thị trường."],"Rủi ro chính là mất neo: giá lệch khỏi 1 USD khi thị trường nghi ngờ tài sản đảm bảo hoặc cơ chế. Tại EU, quy định MiCA cho stablecoin áp dụng từ 30/6/2024, nên một số sàn hạn chế stablecoin chưa tuân thủ cho người dùng EU. Quy định ở các nước khác nhau."],"example":"Giả sử bạn bán 0,1 BTC ở giá 65.000 USDT và nhận 6.500 USDT để chờ cơ hội. Một tháng sau, BTC biến động mạnh nhưng số dư của bạn vẫn khoảng 6.500 USD. Nếu trong một đợt hoảng loạn stablecoin đó tạm giao dịch ở 0,97 USD, giá trị tạm thời còn khoảng 6.305 USD cho đến khi giá về lại neo.","mistakes":["Coi mọi stablecoin là rủi ro như nhau mà không xem cơ chế đảm bảo.","Gửi stablecoin sai mạng vì cùng tên USDT trên nhiều blockchain.","Bị hấp dẫn bởi stablecoin mới trả lãi rất cao mà không hỏi lãi đến từ đâu."],"faq":[{"q":"Stablecoin có mất giá được không?","a":"Có. Stablecoin có thể mất neo tạm thời hoặc lâu dài nếu tài sản đảm bảo hay cơ chế gặp vấn đề, như từng xảy ra với một số stablecoin thuật toán."},{"q":"Nên dùng USDT hay USDC?","a":"Cả hai đều neo theo USD nhưng khác đơn vị phát hành, mức độ công bố và quy định áp dụng. Lựa chọn thường tùy sàn bạn dùng, mạng lưới và khu vực bạn sống."}],"title":"Stablecoin là gì? Các loại đồng tiền ổn định","description":"Stablecoin là gì, các loại stablecoin pháp định, thế chấp crypto và tổng hợp, cách giữ neo và rủi ro mất neo cần biết.","related":[["usdt","USDT (Tether)","USDT là stablecoin do công ty Tether phát hành, neo theo tỷ lệ 1 USDT bằng 1 USD và là đồng ổn định được giao dịch nhiều nhất trên các sàn crypto."],["usdc","USDC (USD Coin)","USDC là stablecoin do công ty Circle phát hành, neo 1:1 với đô la Mỹ và được đảm bảo bằng tiền mặt cùng tài sản ngắn hạn tương đương tiền."],["depeg","Depeg (mất neo giá)","Depeg là tình trạng một stablecoin hoặc token được neo giá rời khỏi mức giá mục tiêu của nó, ví dụ USDT hay USDC giao dịch ở 0,97 USD thay vì 1 USD."],["crypto-backed-stablecoin","Stablecoin thế chấp bằng crypto","Stablecoin thế chấp bằng crypto là stablecoin được đúc ra khi người dùng khóa tài sản crypto như ETH vào hợp đồng thông minh với giá trị lớn hơn số stablecoin nhận được."],["synthetic-dollar","Đô la tổng hợp (stablecoin delta trung tính)","Đô la tổng hợp là token giữ giá quanh 1 USD bằng cách nắm giữ crypto đồng thời mở vị thế short tương ứng trên hợp đồng vĩnh cửu, để lãi lỗ hai bên triệt tiêu nhau."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT có phải là đô la không? Tại sao mua coin lại thấy nó khắp nơi?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false}});
